31	    public static List<Integer> bfs(List<List<Integer>> adjacencyList) {
32	        Objects.requireNonNull(adjacencyList, "adjacencyList");
33	
34	        int vertexCount = adjacencyList.size();
35	        boolean[] visited = new boolean[vertexCount];
36	        List<Integer> result = new ArrayList<>(vertexCount);
37	
38	        for (int vertex = 0; vertex < vertexCount; vertex++) {
39	            if (!visited[vertex]) {
40	                bfsComponent(adjacencyList, vertex, visited, result);
41	            }
42	        }
43	        return result;
44	    }
